import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import {promptBuilder, sessionWith, rejectingWith} from './testSupport.js';

describe('ChatOrchestrator onError on null rejection', () => {
  it('calls onError with an Error when provider rejects with null', async () => {
    let receivedError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        receivedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(rejectingWith(null), promptBuilder, undefined, {hooks});

    let thrown: unknown;
    try {
      await orchestrator.processMessage(sessionWith('hello'));
    } catch (e) {
      thrown = e;
    }

    expect(thrown).toBe(null);
    expect(receivedError).toBeInstanceOf(Error);
    expect(receivedError?.cause).toBe(null);
  });
});

