  const {thrown, receivedError} = await runTest(reason);

  expect({
    thrown,
    isError: receivedError instanceof Error,
    message: receivedError?.message,
    cause: receivedError?.cause,
  }).toEqual({
    thrown: reason,
    isError: true,
    message: 'internal error',
    cause: reason,
  });
});

} catch (error) {
  if (hooks?.onError) {
    const message =
      typeof error === 'object' && error !== null && 'message' in error && typeof error.message === 'string'
        ? error.message
        : String(error);
    const errorInstance = error instanceof Error ? error : new Error(message, {cause: error});
    await hooks.onError(session, errorInstance);
  }
  throw error;
}

